import { 
  MeshBasicNodeMaterial, 
  TextureNode, 
  uv, 
  mix, 
  vec4, 
  color, 
  float 
} from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Destructure config with fallbacks
  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const imageSrc = config.imageUrl ?? '/prism-mock/home/nodes/orb-decor.png';

  // Master Group
  const masterGroup = new Group();

  // Create Backdrop / Surface Plane (~7x6 units at z=-2.5 as instructed by Stage Design Law)
  // This satisfies the "STAGES, never void" requirement with a vertical engineered gradient
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();

  // vertical gradient from surface near-black to ink
  const vUv = uv().y;
  backdropMat.colorNode = mix(
    color(colors.surface),
    color(colors.ink),
    vUv
  );

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  masterGroup.add(backdropMesh);

  // Surface Card Container (the features card body)
  const cardGeo = new PlaneGeometry(2.4, 1.6);
  const cardMat = new MeshBasicNodeMaterial();

  // Custom TSL Shader with subtle gradient & "soft noise / grain" representation
  const cardUv = uv();
  const gradNode = mix(color(colors.surface), color('#1a1a24'), cardUv.y);
  // Simple noise representation using sin/cos of uv coordinates for subtle grain structure
  const grainNode = float(cardUv.x.mul(12345.0).sin().mul(cardUv.y.mul(67890.0).sin()).fraction().mul(0.04));
  cardMat.colorNode = vec4(gradNode.rgb().add(grainNode), 1.0);

  const cardMesh = new Mesh(cardGeo, cardMat);
  masterGroup.add(cardMesh);

  // Subtle Accent Border Rim
  const borderGeo = new PlaneGeometry(2.42, 1.62);
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.colorNode = color(colors.accent);
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.set(0, 0, -0.001);
  masterGroup.add(borderMesh);

  // Textured graphic overlay representing the orb-decor image
  const contentMat = new MeshBasicNodeMaterial({ transparent: true });
  const contentMesh = new Mesh(new PlaneGeometry(2.2, 1.0), contentMat);
  contentMesh.position.set(0, 0.22, 0.002);
  masterGroup.add(contentMesh);

  // Load Image via ctx.textureLoader
  ctx.textureLoader.loadTexture(imageSrc).then((tex) => {
    if (tex) {
      contentMat.colorNode = new TextureNode(tex);
      contentMat.needsUpdate = true;
    }
  }).catch((err) => {
    console.warn('Failed loading texture in card-label Node:', err);
    // Fallback visually rich representation on fail
    contentMat.colorNode = vec4(color(colors.accent).rgb(), float(0.35));
    contentMat.needsUpdate = true;
  });

  // Text Content Render: "Features 2"
  const textItems = config.textContent ?? visualSpec.textContent ?? [];
  const textString = textItems[0]?.text ?? 'Features 2';

  // High contrast text conforming to monochrome / accent guidelines (paper color)
  const textObj = ctx.fontAtlas.createText(textString, {
    fontSize: 0.14, // 39px target matched dynamically in system space units
    color: colors.paper,
    align: 'center'
  });
  textObj.position.set(0, -0.45, 0.005);
  masterGroup.add(textObj);

  // Apply Cinematic Primitives if present safely
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
        const pInstance = ctx.primitives[prim.name](masterGroup, prim.params);
        if (pInstance) activePrimitives.push(pInstance);
      }
    });
  }

  // Entrance Motion (Rise-in preset with subtle settle)
  gsap.fromTo(masterGroup.position,
    { y: -0.4 },
    { y: 0.0, duration: 0.8, ease: 'power3.out' }
  );

  // Cleanup block
  masterGroup.userData = {
    handlers: {},
    cleanup() {
      // Dispose Geometries
      backdropGeo.dispose();
      cardGeo.dispose();
      borderGeo.dispose();
      contentMesh.geometry.dispose();

      // Dispose Materials
      backdropMat.dispose();
      cardMat.dispose();
      borderMat.dispose();
      contentMat.dispose();

      // Clear GSAP and Primitives
      gsap.killTweensOf(masterGroup.position);
      activePrimitives.forEach((p) => {
        if (typeof p.cleanup === 'function') p.cleanup();
      });
    }
  };

  return masterGroup;
}
